MENU.forEach((c,i)=>c.items.forEach((it,j)=>{it.k=i+'-'+j;it.cat=c.name;it.slug=it.n.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');it.fb=it.img||c.fb;it.cl=it.img?'':(it.c!==undefined?it.c:c.c)}));


const $=s=>document.querySelector(s), fmt=n=>'C$'+n.toLocaleString('es-NI');
const chips=$('#chips'), list=$('#list'), modal=$('#modal');
let lock=false;
const pic=(it,cls)=>`<div class="ph ${cls||''}"><img loading="lazy" src="${it.fb}" alt="${it.n}" class="${it.cl}"></div>`;
const find=k=>{const [i,j]=k.split('-');return MENU[i].items[j]};
const io=new IntersectionObserver(es=>{if(lock)return;es.forEach(e=>{if(e.isIntersecting)setActive(e.target.id)})},{rootMargin:'-30% 0px -65% 0px'});
function setActive(id){chips.querySelectorAll('.chip').forEach(b=>{const on=b.dataset.id===id;b.setAttribute('aria-selected',on);if(on)b.scrollIntoView({inline:'center',block:'nearest',behavior:'smooth'})})}
function render(q=''){
  q=q.trim().toLowerCase();chips.innerHTML='';list.innerHTML='';let any=false;
  MENU.forEach(c=>{
    const its=c.items.filter(it=>!q||(it.n+' '+it.d).toLowerCase().includes(q));if(!its.length)return;any=true;
    chips.insertAdjacentHTML('beforeend',`<button class="chip" role="tab" data-id="${c.id}" aria-selected="false">${c.name}</button>`);
    list.insertAdjacentHTML('beforeend',`<section id="${c.id}"><h2>${c.name}</h2>${its.map(it=>`
      <button class="item" data-k="${it.k}">${pic(it)}
        <span class="txt"><h3>${it.n}${it.star?'<span class="tag">Favorito</span>':''}</h3><p>${it.d}</p><span class="price">${fmt(it.p)}</span></span>
      </button>`).join('')}</section>`);
  });
  $('#empty').style.display=any?'none':'block';
  document.querySelectorAll('main section').forEach(s=>io.observe(s));
  const f=chips.querySelector('.chip');if(f)f.setAttribute('aria-selected','true');
}
chips.addEventListener('click',e=>{const b=e.target.closest('.chip');if(!b)return;lock=true;setActive(b.dataset.id);document.getElementById(b.dataset.id).scrollIntoView();setTimeout(()=>lock=false,700)});
$('#q').addEventListener('input',e=>render(e.target.value));
list.addEventListener('click',e=>{
  const b=e.target.closest('.item');if(!b)return;const it=find(b.dataset.k);
  $('#mb').innerHTML=`<div class="big">${pic(it)}<button class="x" data-x aria-label="Cerrar">×</button></div><div class="mb"><small>${it.cat}</small><h3>${it.n}</h3><p>${it.d}</p><span class="price">${fmt(it.p)}</span></div>`;
  modal.showModal();
});
modal.addEventListener('click',e=>{if(e.target===modal||e.target.closest('[data-x]'))modal.close()});
render();
